-- cap_class_fill.sql  (generated 2026-10-11)
-- Fills gaps in the class/subclass tables from Cap's Eldridia Player Guide data
-- (player-guide/mechanics.json, generated 2026-10-09 from mechanics.md), plus the
-- 2026-10-08 class-levels-seed.json for short subclass_levels descriptions.
-- Idempotent and non-destructive: only adds tables/columns/rows and fills NULL / placeholder
-- values. Never overwrites a value Gabriel already has. Safe to re-run.
SET client_encoding = 'UTF8';
BEGIN;

-- ---------- schema ----------
ALTER TABLE classes ADD COLUMN IF NOT EXISTS saving_throws TEXT[];
ALTER TABLE classes ADD COLUMN IF NOT EXISTS armor_proficiencies TEXT;
ALTER TABLE classes ADD COLUMN IF NOT EXISTS weapon_proficiencies TEXT;
ALTER TABLE classes ADD COLUMN IF NOT EXISTS tool_proficiencies TEXT;
ALTER TABLE classes ADD COLUMN IF NOT EXISTS skill_choice_count INTEGER;
ALTER TABLE classes ADD COLUMN IF NOT EXISTS skill_options TEXT[];
ALTER TABLE classes ADD COLUMN IF NOT EXISTS skill_fixed TEXT[];
ALTER TABLE classes ADD COLUMN IF NOT EXISTS class_dc TEXT;
ALTER TABLE classes ADD COLUMN IF NOT EXISTS spellcasting TEXT;
ALTER TABLE classes ADD COLUMN IF NOT EXISTS spellcasting_stat TEXT;
ALTER TABLE classes ADD COLUMN IF NOT EXISTS caster_type TEXT;
ALTER TABLE classes ADD COLUMN IF NOT EXISTS subclass_level INTEGER;
ALTER TABLE classes ADD COLUMN IF NOT EXISTS subclass_feature_levels INTEGER[];
ALTER TABLE classes ADD COLUMN IF NOT EXISTS titles TEXT;

ALTER TABLE class_levels ADD COLUMN IF NOT EXISTS proficiency_bonus INTEGER;
ALTER TABLE class_levels ADD COLUMN IF NOT EXISTS resources TEXT;

CREATE TABLE IF NOT EXISTS class_features (
    id            SERIAL PRIMARY KEY,
    class_id      INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
    level         INTEGER NOT NULL CHECK (level BETWEEN 1 AND 30),
    name          TEXT NOT NULL,
    description   TEXT NOT NULL,
    feature_type  TEXT NOT NULL CHECK (feature_type IN ('feature','choice','boost','proficiency','resource','title')),
    source        TEXT NOT NULL CHECK (source IN ('canon','new','approved')),
    approved_date DATE,
    sort_order    INTEGER NOT NULL DEFAULT 0,
    UNIQUE (class_id, level, name)
);

CREATE TABLE IF NOT EXISTS subclass_features (
    id            SERIAL PRIMARY KEY,
    subclass_id   INTEGER NOT NULL REFERENCES sub_classes(id) ON DELETE CASCADE,
    level         INTEGER NOT NULL CHECK (level BETWEEN 1 AND 30),
    name          TEXT NOT NULL,
    description   TEXT NOT NULL,
    feature_type  TEXT NOT NULL CHECK (feature_type IN ('feature','choice','boost','proficiency','resource','title')),
    source        TEXT NOT NULL CHECK (source IN ('canon','new','approved')),
    approved_date DATE,
    sort_order    INTEGER NOT NULL DEFAULT 0,
    UNIQUE (subclass_id, level, name)
);

CREATE TABLE IF NOT EXISTS class_spell_slots (
    id          SERIAL PRIMARY KEY,
    class_id    INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
    level       INTEGER NOT NULL CHECK (level BETWEEN 1 AND 30),
    slot_level  INTEGER NOT NULL CHECK (slot_level BETWEEN 1 AND 9),
    slots       INTEGER NOT NULL CHECK (slots > 0),
    UNIQUE (class_id, level, slot_level)
);

-- the UNIQUE constraints above already index (owner_id, level, ...); these cover the
-- existing tables and FK lookups explicitly
CREATE INDEX IF NOT EXISTS class_features_class_id_level_idx       ON class_features (class_id, level);
CREATE INDEX IF NOT EXISTS subclass_features_subclass_id_level_idx ON subclass_features (subclass_id, level);
CREATE INDEX IF NOT EXISTS class_spell_slots_class_id_level_idx    ON class_spell_slots (class_id, level);
CREATE INDEX IF NOT EXISTS sub_classes_class_id_idx                ON sub_classes (class_id);

-- ---------- subclass name map (doc name -> current DB name; DB names are NOT renamed) ----------
CREATE TEMP TABLE cap_subclass_map (class_name TEXT, doc_name TEXT, db_name TEXT) ON COMMIT DROP;
