-- ---------- classes: fill new 1:1 columns (only where NULL) and placeholder descriptions ----------
UPDATE classes c SET
    description             = CASE WHEN c.description IS NULL OR btrim(c.description) = '' OR c.description = 'Pending Understanding' THEN v.description ELSE c.description END,
    saving_throws           = COALESCE(c.saving_throws, v.saving_throws),
    armor_proficiencies     = COALESCE(c.armor_proficiencies, v.armor),
    weapon_proficiencies    = COALESCE(c.weapon_proficiencies, v.weapons),
    tool_proficiencies      = COALESCE(c.tool_proficiencies, v.tools),
    skill_choice_count      = COALESCE(c.skill_choice_count, v.skill_count),
    skill_options           = COALESCE(c.skill_options, v.skill_options),
    skill_fixed             = COALESCE(c.skill_fixed, v.skill_fixed),
    class_dc                = COALESCE(c.class_dc, v.class_dc),
    spellcasting            = COALESCE(c.spellcasting, v.spellcasting),
    spellcasting_stat       = COALESCE(c.spellcasting_stat, v.spellcasting_stat),
    caster_type             = COALESCE(c.caster_type, v.caster_type),
    subclass_level          = COALESCE(c.subclass_level, v.subclass_level),
    subclass_feature_levels = COALESCE(c.subclass_feature_levels, v.subclass_feature_levels),
    titles                  = COALESCE(c.titles, v.titles)
FROM (VALUES
  ('Warrior','The Warrior relies on Strength (attacks, damage, Warrior class DCs). Spellcasting: None. At level 3 you choose one of 3 subclasses: Vanguard, Weaponmaster, Warlord. Titles: L30 Apex Warrior.',ARRAY['STR','CON']::text[],'All armor and shields','All simple and martial weapons','None',2,ARRAY['Acrobatics','Animal Handling','Athletics','History','Insight','Intimidation','Perception','Survival']::text[],'{}'::text[],'8 + PB + STR modifier','None',NULL,NULL,3,ARRAY[3,6,10,14,18,24,28]::int[],'L30 Apex Warrior'),
  ('Mage','The Mage relies on Intelligence (spell attack, spell save DC, arcane features). Spellcasting: Full caster, INT; slots per Shared Frame full-caster table. At level 3 you choose one of 3 subclasses: Evoker, Runeweaver, Scholar. Titles: L30 Apex Mage.',ARRAY['INT','WIS']::text[],'None (Runeweaver adds light armor at 3)','Staves, daggers, darts, slings (Runeweaver adds martial blades at 3)','None',2,ARRAY['Arcana','History','Insight','Investigation','Medicine','Religion']::text[],'{}'::text[],'8 + PB + INT modifier (spell attack = PB + INT modifier)','Full caster, INT; slots per Shared Frame full-caster table','INT','full',3,ARRAY[3,6,10,14,18,24,28]::int[],'L30 Apex Mage'),
  ('Witch','The Witch relies on Charisma (hex save DC, curse attacks, witch features). Spellcasting: Hybrid (2/3) caster, CHA; slots per Shared Frame hybrid table. At level 3 you choose one of 5 subclasses: Hex Magic, Blood Magic, Fate Magic, Green Magic, Witch Knight. Titles: L20 Crone / Warlock; L30 Apex Witch.',ARRAY['WIS','CHA']::text[],'Light armor; Witch Knight adds medium armor. No shields for any Witch, including Witch Knight','Simple weapons + ritual blade (a dagger or sickle that counts as your focus); Witch Knight adds martial melee weapons','Herbalism kit',2,ARRAY['Arcana','Deception','Insight','Intimidation','Medicine','Nature','Religion']::text[],'{}'::text[],'8 + PB + CHA modifier (spell attack = PB + CHA modifier)','Hybrid (2/3) caster, CHA; slots per Shared Frame hybrid table','CHA','hybrid',3,ARRAY[3,6,10,14,18,20,24,28]::int[],'L20 Crone / Warlock; L30 Apex Witch'),
  ('Paladin','The Paladin relies on Charisma (oath DC, smites, auras); Strength recommended for weapon attacks. Spellcasting: Half caster from level 2, CHA; slots per Shared Frame half-caster table (top tier 6th). At level 3 you choose one of 4 subclasses: Oath of Ochre, Oath of Umber, Oath of Shadows, Oath of Starlight. Titles: L30 Arch Paladin.',ARRAY['WIS','CHA']::text[],'All armor and shields','Simple and martial weapons','None',2,ARRAY['Athletics','Insight','Intimidation','Medicine','Persuasion','Religion']::text[],'{}'::text[],'8 + PB + CHA modifier (spell attack = PB + CHA modifier)','Half caster from level 2, CHA; slots per Shared Frame half-caster table (top tier 6th)','CHA','half',3,ARRAY[3,7,15,18,20,24,28]::int[],'L30 Arch Paladin'),
  ('Assassin','The Assassin relies on Dexterity (finesse/ranged attacks, poison and gadget DCs, stealth features). Spellcasting: None. At level 3 you choose one of 3 subclasses: Shadowblade, Venom Bound, Ghost Walker. Titles: L30 Apex Assassin.',ARRAY['DEX','INT']::text[],'Light armor','Simple weapons, finesse martial weapons, hand crossbows; plus your choice of shortbows or longbows at level 1','Thieves'' tools at 1; poisoner''s kit or disguise kit at 3',3,ARRAY['Acrobatics','Athletics','Deception','Insight','Intimidation','Investigation','Perception','Sleight of Hand']::text[],ARRAY['Stealth']::text[],'8 + PB + DEX modifier','None',NULL,NULL,3,ARRAY[3,6,10,14,18,24,28]::int[],'L30 Apex Assassin'),
  ('Knight','The Knight relies on Strength (attacks, shove/override DCs, mounted features); Charisma optional for Crown Guard. Spellcasting: None. At level 3 you choose one of 3 subclasses: Cavalier, Shieldbearer, Crown Guard. Titles: L30 Apex Knight.',ARRAY['CON','CHA']::text[],'Light, medium, and heavy armor and shields','Simple and martial melee weapons, lances','None',2,ARRAY['Animal Handling','Athletics','History','Insight','Intimidation','Persuasion','Religion']::text[],'{}'::text[],'8 + PB + STR modifier (Crown Guard may use CHA for its features)','None',NULL,NULL,3,ARRAY[3,6,10,14,18,24,28]::int[],'L30 Apex Knight'),
  ('Ranger','The Ranger relies on Dexterity (attacks, class features); Wisdom secondary for tracking and spell DC. Spellcasting: Half caster from level 2, WIS; slots per Shared Frame half-caster table (top tier 6th). At level 3 you choose one of 3 subclasses: Archer, Tamer, Stalker. Titles: L30 Apex Ranger.',ARRAY['STR','DEX']::text[],'Light and medium armor and shields','Simple and martial weapons','None',3,ARRAY['Animal Handling','Athletics','Insight','Investigation','Nature','Perception','Stealth','Survival']::text[],'{}'::text[],'8 + PB + DEX modifier for class features; spell DC 8 + PB + WIS modifier','Half caster from level 2, WIS; slots per Shared Frame half-caster table (top tier 6th)','WIS','half',3,ARRAY[3,6,10,14,18,24,28]::int[],'L30 Apex Ranger'),
  ('Druid','The Druid relies on Wisdom (spell DC, Wild Shape, nature features). Spellcasting: Full caster, WIS; slots per Shared Frame full-caster table. At level 3 you choose one of 3 subclasses: Circle of Roots, Circle of Beasts, Circle of Seasons. Titles: L20 Archdruid; L30 Apex Druid.',ARRAY['INT','WIS']::text[],'Light and medium armor (non-metal) and shields (non-metal)','Simple weapons plus scimitar, sickle, spear, staff, dart, sling, club','Herbalism kit',2,ARRAY['Animal Handling','Arcana','Insight','Medicine','Nature','Perception','Religion','Survival']::text[],'{}'::text[],'8 + PB + WIS modifier (spell attack = PB + WIS modifier)','Full caster, WIS; slots per Shared Frame full-caster table','WIS','full',3,ARRAY[3,6,10,14,18,24,28]::int[],'L20 Archdruid; L30 Apex Druid'),
  ('Berserker','The Berserker relies on Strength (CON secondary). Spellcasting: None. At level 3 you choose one of 3 subclasses: Frenzy, Ironhide, Bloodwake. Titles: L30 Wrathborn (Mythic Rage).',ARRAY['STR','CON']::text[],'Light and medium armor; no heavy armor, no shields','Simple and martial melee weapons (thrown weapons allowed; no bows as class weapons)','None',2,ARRAY['Animal Handling','Athletics','Intimidation','Nature','Perception','Survival']::text[],'{}'::text[],'8 + PB + STR modifier','None',NULL,NULL,3,ARRAY[3,6,10,14,18,24,28]::int[],'L30 Wrathborn (Mythic Rage)'),
  ('Pugilist','The Pugilist relies on Dexterity (CON secondary; STR optional for grapple builds). Spellcasting: None. At level 3 you choose one of 3 subclasses: Way of the Tiger, Way of the Bear, Way of Iron. Titles: L30 Grand Master.',ARRAY['STR','DEX']::text[],'None (Unarmored Defense); no shields','Unarmed strikes, simple melee weapons, knuckles/cestus/gauntlets (these use your unarmed die)','None',2,ARRAY['Acrobatics','Athletics','History','Insight','Religion','Stealth']::text[],'{}'::text[],'8 + PB + DEX modifier (or STR for grapple builds)','None',NULL,NULL,3,ARRAY[3,6,10,14,18,24,28]::int[],'L30 Grand Master'),
  ('Lancer','The Lancer relies on Strength (Dexterity optional with finesse spears). Spellcasting: None. At level 3 you choose one of 3 subclasses: Phalanx, Skyreach, Twinstrike. Titles: L30 Dragonspear.',ARRAY['STR','DEX']::text[],'Light, medium, and heavy armor and shields (canon lists medium and heavy; change approved in principle 2026-09-25, not yet locked)','Simple melee weapons; spears, pikes, glaives, halberds, lances, and other polearms. Reach: spears 5 ft; other polearms 10 ft','None',2,ARRAY['Acrobatics','Animal Handling','Athletics','History','Insight','Intimidation','Perception']::text[],'{}'::text[],'8 + PB + STR modifier (or DEX if you attack with a finesse spear)','None',NULL,NULL,3,ARRAY[3,6,10,14,18,24,28]::int[],'L30 Dragonspear'),
  ('Priest','The Priest relies on Wisdom (spell DC, Channel Divinity, healing). Spellcasting: Full caster, WIS; slots per Shared Frame full-caster table. At level 3 you choose one of 3 subclasses: Lightbearer, Binder, Shadow Whisper. Titles: L20 High Priest; L30 Arch Priest.',ARRAY['WIS','CHA']::text[],'Light and medium armor and shields','Simple weapons','None',2,ARRAY['History','Insight','Medicine','Persuasion','Religion']::text[],'{}'::text[],'8 + PB + WIS modifier (spell attack = PB + WIS modifier)','Full caster, WIS; slots per Shared Frame full-caster table','WIS','full',3,ARRAY[3,6,10,14,18,24,28]::int[],'L20 High Priest; L30 Arch Priest'),
  ('Summoner','The Summoner relies on Charisma (binding, summon command, spell DC). Spellcasting: Half caster, rounded up (slots from level 1), CHA; slots per Shared Frame half-caster (rounded up) table (top tier 6th). At level 3 you choose one of 3 subclasses: Necromancer, Hollowmancer, Technomancer. Titles: L20 Lich; L30 Arch Lich.',ARRAY['CON','CHA']::text[],'Light armor','Simple weapons and a focus','None',2,ARRAY['Arcana','Deception','History','Intimidation','Investigation','Religion']::text[],'{}'::text[],'8 + PB + CHA modifier (spell attack = PB + CHA modifier; summons use these)','Half caster, rounded up (slots from level 1), CHA; slots per Shared Frame half-caster (rounded up) table (top tier 6th)','CHA','half_rounded_up',3,ARRAY[3,6,10,14,18,24,28]::int[],'L20 Lich; L30 Arch Lich'),
  ('Songsmith','The Songsmith relies on Charisma (spells, Inspiration, voice features). Spellcasting: Full caster, CHA (support and control); slots per Shared Frame full-caster table. At level 3 you choose one of 3 subclasses: Warsong, Loresong, Diresong. Titles: L20 Maestro; L30 Renowned Songbird.',ARRAY['DEX','CHA']::text[],'Light armor and shields','Simple weapons, rapier, shortsword, hand crossbow; instruments as focus','One musical instrument',3,ARRAY['any']::text[],'{}'::text[],'8 + PB + CHA modifier (spell attack = PB + CHA modifier)','Full caster, CHA (support and control); slots per Shared Frame full-caster table','CHA','full',3,ARRAY[3,6,10,14,18,24,28]::int[],'L20 Maestro; L30 Renowned Songbird')
) AS v(class_name, description, saving_throws, armor, weapons, tools, skill_count, skill_options, skill_fixed, class_dc, spellcasting, spellcasting_stat, caster_type, subclass_level, subclass_feature_levels, titles)
WHERE lower(c.name) = lower(v.class_name);

