  ('Pugilist','Way of the Tiger','Pugilist subclass, chosen at level 3. Features: Tiger''s Rush (3); Pounce (6); Raking Flurry (10); Predator''s Eye (14); Hunting Rhythm (18); Mythic Tiger (24); Sovereign Cat (28).'),
  ('Pugilist','Way of the Bear','Pugilist subclass, chosen at level 3. Features: Crushing Grab (3); Thick Hide (6); Maul (10); Unbearable Hold (14); Hibernating Guard (18); Mythic Bear (24); Mountain''s Hug (28).'),
  ('Pugilist','Way of Iron','Pugilist subclass, chosen at level 3. Features: Iron Bones (3); Break Guard (6); Shockwave Palm (10); Shatterplate (14); Siege Fists (18); Mythic Iron (24); Living Anvil (28).'),
  ('Lancer','Phalanx','Lancer subclass, chosen at level 3. Features: Lockstep (3); Wall of Points (6); Hold Fast (10); Combined Brace (14); Fortress Line (18); Mythic Phalanx (24); Unbroken Spearwall (28).'),
  ('Lancer','Skyreach','Lancer subclass, chosen at level 3. Features: Vault Strike (3); Leaping Charge (6); Aerial Threat (10); Dragoon Descent (14); Skyhook (18); Mythic Vault (24); Starfall Lance (28).'),
  ('Lancer','Twinstrike','Lancer subclass, chosen at level 3. Features: Twin Fangs (3); Crossed Guard (6); Double Brace (10); Flurry of Points (14); Paired Sentinel (18); Mythic Twinstrike (24); Two Spear Tempest (28).'),
  ('Priest','Lightbearer','Priest subclass, chosen at level 3. Features: Radiant Flood (3); Coronal Ward (6); Dawnfire (10); Mass Disciple (14); Sun Mantle (18); Mythic Halo (24); Day Without Night (28).'),
  ('Priest','Binder','Priest subclass, chosen at level 3. Features: Seal (3); Abjure (6); Circle of Binding (10); Hollow-Breaker (14); Soul Lock (18); Mythic Sigil (24); Absolute Seal (28).'),
  ('Priest','Shadow Whisper','Priest subclass, chosen at level 3. Features: Whisper in the Dark (3); Umbra Sight (6); Secret Debt (10); Shadow Step, Sacred (14); Congregation of Whispers (18); Mythic Umbra Choir (24); Night''s Confessor (28).'),
  ('Summoner','Necromancer','Summoner subclass, chosen at level 3. Features: Bone Servant (3); Grave Command (6); Soul Relay (10); Remnant Army (14); Death Knight Guard (18); Mythic Ossuary (24); Door of the Dead (28).'),
  ('Summoner','Hollowmancer','Summoner subclass, chosen at level 3. Features: Hollow Spark (3); Shared Hunger (6); Rot Mark (10); Hollow Pack (14); Break the Seal (18); Mythic Rot Choir (24); Spell Rot Sovereign (28).'),
  ('Summoner','Technomancer','Summoner subclass, chosen at level 3. Features: Scrap Drone (3); Overclock (6); Iron Phalanx (10); Siege Frame (14); Black Gate Echo (18); Mythic Assembly (24); Voice Beyond the Gate (28).'),
  ('Songsmith','Warsong','Songsmith subclass, chosen at level 3. Features: Battle Chorus (3); Fear Breaker (6); War Cadence (10); Thunder Refrain (14); March of Conquest (18); Mythic War Anthem (24); Unbroken Legion (28).'),
  ('Songsmith','Loresong','Songsmith subclass, chosen at level 3. Features: Cutting Words (3); Universal Tongue (6); Peerless Skill (10); Stolen Lore (14); Living Library (18); Mythic Chronicle (24); Write the Room (28).'),
  ('Songsmith','Diresong','Songsmith subclass, chosen at level 3. Features: Tolling Note (3); Requiem Ward (6); Silence Between Notes (10); Funeral March (14); Umbria''s Echo (18); Mythic Lament (24); Last Song (28).')
) AS v(class_name, sub_name, description),
     cap_subclass_map mp, classes c
WHERE mp.class_name = v.class_name AND mp.doc_name = v.sub_name
  AND lower(c.name) = lower(mp.class_name)
  AND s.class_id = c.id AND lower(btrim(s.name)) = lower(mp.db_name)
  AND (s.description IS NULL OR btrim(s.description) = '');

