UPDATE class_levels cl SET
    proficiency_bonus = COALESCE(cl.proficiency_bonus, v.pb),
    resources         = COALESCE(cl.resources, v.resources)
FROM cap_class_level_data v JOIN classes c ON lower(c.name) = lower(v.class_name)
WHERE cl.class_id = c.id AND cl.level = v.level
  AND (cl.proficiency_bonus IS NULL OR (cl.resources IS NULL AND v.resources IS NOT NULL));

