JOIN cap_subclass_map mp ON mp.class_name=v.class_name AND mp.doc_name=v.sub_name JOIN classes c ON lower(c.name)=lower(mp.class_name) JOIN sub_classes s ON s.class_id=c.id AND lower(btrim(s.name))=lower(mp.db_name)
ON CONFLICT (subclass_id, level) DO NOTHING;

